<?php
// Private CLI: link an authoritative political application to one closed receipt ticket.
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}ini_set('display_errors','0');
try{
 $v=json_decode(stream_get_contents(STDIN,65536),true,12,JSON_THROW_ON_ERROR);foreach(['applicationId','userId']as$k)if(!preg_match('/^[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}$/i',$v[$k]??''))throw new Exception('Invalid identity');
 $c=json_decode(file_get_contents('/home/dunerealms/.config/integrations.json'),true);$db=new PDO('mysql:host='.$c['host'].';dbname='.$c['database'].';charset=utf8mb4',$c['username'],$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
 $db->exec('CREATE TABLE IF NOT EXISTS dune_political_application_tickets(application_id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,ticket_id INT UNSIGNED NULL UNIQUE,state VARCHAR(16) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB');
 $q=$db->prepare('SELECT GET_LOCK(?,10)');$q->execute(['dune-app:'.$v['applicationId']]);if((int)$q->fetchColumn()!==1)throw new Exception('Busy');
 $q=$db->prepare('SELECT a.*,t.number FROM dune_political_application_tickets a LEFT JOIN drsupport_ticket t ON t.ticket_id=a.ticket_id WHERE application_id=?');$q->execute([$v['applicationId']]);$existing=$q->fetch();$recoverTicketId=null;if($existing){if($existing['user_id']!==$v['userId'])throw new Exception('Applicant binding conflict');if($existing['state']==='created'&&$existing['ticket_id']){echo json_encode(['ok'=>true,'ticketId'=>(int)$existing['ticket_id'],'ticketNumber'=>$existing['number'],'replay'=>true]);exit;}if($existing['ticket_id'])$recoverTicketId=(int)$existing['ticket_id'];else{$q=$db->prepare("SELECT t.ticket_id FROM drsupport_ticket t JOIN drsupport_ticket__cdata c ON c.ticket_id=t.ticket_id JOIN drsupport_user_email e ON e.user_id=t.user_id JOIN drsupport_help_topic h ON h.topic_id=t.topic_id WHERE e.address=? AND c.subject=? AND h.topic='Election application receipt' AND t.created>=? LIMIT 2");$q->execute([$v['userId'].'@accounts.dunerealms.invalid','Election application · '.$v['publicId'],$existing['created_at']]);$found=$q->fetchAll(PDO::FETCH_COLUMN);if(count($found)!==1)throw new Exception('Previous receipt requires review');$recoverTicketId=(int)$found[0];}}

 $dept=$db->query("SELECT id FROM drsupport_department WHERE name='Support' LIMIT 1")->fetchColumn();$q=$db->prepare("SELECT topic_id FROM drsupport_help_topic WHERE topic='Election application receipt' LIMIT 1");$q->execute();$topic=$q->fetchColumn();
 if(!$topic){$row=$db->query("SELECT * FROM drsupport_help_topic WHERE topic='General support' LIMIT 1")->fetch();if(!$row||!$dept)throw new Exception('Support intake unavailable');unset($row['topic_id']);$row['topic']='Election application receipt';$row['ispublic']=0;$row['noautoresp']=1;$row['dept_id']=$dept;$row['team_id']=0;$row['staff_id']=0;$row['created']=$row['updated']=gmdate('Y-m-d H:i:s');$cols=array_keys($row);$q=$db->prepare('INSERT INTO drsupport_help_topic (`'.implode('`,`',$cols).'`) VALUES('.implode(',',array_fill(0,count($row),'?')).')');$q->execute(array_values($row));$topic=$db->lastInsertId();$q=$db->prepare("INSERT INTO drsupport_help_topic_form(topic_id,form_id,sort,extra) VALUES(?,2,1,'{}')");$q->execute([$topic]);}
 $_SERVER['SCRIPT_NAME']='/political-application-ticket.php';$_SERVER['REMOTE_ADDR']='127.0.0.1';$_SERVER['REQUEST_METHOD']='POST';$_SERVER['SERVER_NAME']=$_SERVER['HTTP_HOST']='support.dunerealms.com';chdir(__DIR__);require __DIR__.'/main.inc.php';
 $name=mb_substr((string)($v['username']??'DuneRealms member'),0,40);$email=$v['userId'].'@accounts.dunerealms.invalid';$user=User::lookupByEmail($email)?:User::fromVars(['name'=>$name,'email'=>$email]);if(!$user)throw new Exception('Applicant identity unavailable');
 if(!$existing){$q=$db->prepare("INSERT INTO dune_political_application_tickets(application_id,user_id,state) VALUES(?,?,'processing')");$q->execute([$v['applicationId'],$v['userId']]);}$subject='Election application · '.mb_substr((string)$v['publicId'],0,32);$text='Application: '.$v['publicId']."\nOffice: ".$v['kind']."\nFaction: ".$v['faction']."\nElection: ".$v['electionDate']."\n\nMotivation:\n".mb_substr((string)$v['motivation'],0,6000)."\n\nThis is an automatic registration receipt, not an approval or rejection. The election register remains authoritative. This receipt is automatically closed; election progress remains available in Realm & Politics.";
 $errors=[];$ticket=$recoverTicketId?Ticket::lookup($recoverTicketId):Ticket::create(['uid'=>$user->getId(),'name'=>$name,'email'=>$email,'topicId'=>(int)$topic,'deptId'=>(int)$dept,'subject'=>$subject,'message'=>nl2br(htmlspecialchars($text,ENT_QUOTES,'UTF-8')),'source'=>'API','ip'=>'127.0.0.1','autorespond'=>false],$errors,'API',false,false);if(!$ticket){$q=$db->prepare('DELETE FROM dune_political_application_tickets WHERE application_id=? AND ticket_id IS NULL');$q->execute([$v['applicationId']]);throw new Exception('Ticket creation failed');}
 $q=$db->prepare('UPDATE dune_political_application_tickets SET ticket_id=? WHERE application_id=?');$q->execute([$ticket->getId(),$v['applicationId']]);
 $errors=[];$closedId=$db->query("SELECT id FROM drsupport_ticket_status WHERE state='closed' ORDER BY CASE WHEN name='Closed' THEN 0 ELSE 1 END,id LIMIT 1")->fetchColumn();$closed=$closedId?TicketStatus::lookup((int)$closedId):null;if(!$closed||!$ticket->setStatus($closed,'Automatic application registration receipt; no election decision made.',$errors,false,true))throw new Exception('Could not close registration receipt');
 $q=$db->prepare("UPDATE dune_ticket_identifiers SET workflow_type='INT',internal_reference=? WHERE ticket_id=?");$q->execute([$v['publicId'],$ticket->getId()]);$q=$db->prepare("UPDATE dune_political_application_tickets SET ticket_id=?,state='created' WHERE application_id=?");$q->execute([$ticket->getId(),$v['applicationId']]);echo json_encode(['ok'=>true,'ticketId'=>$ticket->getId(),'ticketNumber'=>$ticket->getNumber()]);
}catch(Throwable $e){error_log('Political receipt bridge: '.substr($e->getMessage(),0,180));echo '{"error":"Application receipt requires review; no duplicate will be created automatically."}';exit(1);}
